import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"Dashboard & navigation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md","lastUpdated":1791960929000}'),d={name:"guide/dashboard.md"};function n(s,t,i,h,c,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="dashboard-navigation" tabindex="-1">Dashboard &amp; navigation <a class="header-anchor" href="#dashboard-navigation" aria-label="Permalink to &quot;Dashboard &amp; navigation&quot;">​</a></h1><p>The Dashboard is the home screen after login. It shows a tile for every screen you are allowed to open, grouped into buckets.</p><h2 id="buckets" tabindex="-1">Buckets <a class="header-anchor" href="#buckets" aria-label="Permalink to &quot;Buckets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bucket</th><th>Contains</th></tr></thead><tbody><tr><td><strong>Sales</strong></td><td>Sales Invoice, Quotation, Sales Order, Cashier Desk, Cashier Management, Cancellation, Modify Submitted</td></tr><tr><td><strong>Purchase</strong></td><td>Purchase Invoice, Purchase Order, Purchase Desk</td></tr><tr><td><strong>Stock</strong></td><td>Stock Reconciliation, Store Transfer, Repack, Landed Cost Voucher, Stock Check</td></tr><tr><td><strong>Accounts</strong></td><td>Cash Box Entry, Single Entry, Payment Receipt, Unreconciled Entries, Payment Reconciliation, Journal Contra</td></tr><tr><td><strong>Ledger View</strong></td><td>Customer Ledger, General Ledger, GST Ledger</td></tr><tr><td><strong>SSPL Special</strong></td><td>Catalogue, Offer Display, Incentives, Barcode Print, Loading Receipt, Parcel Address</td></tr><tr><td><strong>Report</strong></td><td>Daily Report, Store Sales, Stock Status, Stock Aging, Outstanding Customers and more</td></tr></tbody></table><p>A tile you don&#39;t see is either not in your company&#39;s licence or not granted to your user.</p><h2 id="opening-a-screen" tabindex="-1">Opening a screen <a class="header-anchor" href="#opening-a-screen" aria-label="Permalink to &quot;Opening a screen&quot;">​</a></h2><ul><li>Click the tile, or</li><li>Press the tile&#39;s shortcut key (shown on the tile), or</li><li>Press <strong>F1</strong> to open the Command Line and type the screen name.</li></ul><p>Press <strong>Esc</strong> on most screens to go back to the Dashboard.</p><h2 id="dashboard-shortcuts" tabindex="-1">Dashboard shortcuts <a class="header-anchor" href="#dashboard-shortcuts" aria-label="Permalink to &quot;Dashboard shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Opens</th></tr></thead><tbody><tr><td>Shift+F3</td><td>Payment Receipt</td></tr><tr><td>Shift+F4</td><td>Purchase Desk</td></tr><tr><td>Shift+F5</td><td>Cashier Desk</td></tr><tr><td>Shift+F6</td><td>Customer Ledger</td></tr><tr><td>Shift+F7</td><td>Purchase Order</td></tr><tr><td>Shift+F8</td><td>Journal Contra</td></tr><tr><td>Shift+F9</td><td>Store Transfer</td></tr><tr><td>Shift+F10</td><td>Quotation</td></tr></tbody></table><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Use the theme toggle in the header to switch between light and dark mode. The choice is remembered on that computer.</p>',12)])])}const b=e(d,[["render",n]]);export{g as __pageData,b as default};
